python3 -c "
import json, os
base = '/root/autodl-tmp/event-gated-adaptive-horizon/logdir'
exps = ['baseline_s1','fixed_dt2_v1_s1','exp_008d_subsample_on_h8','exp_008a_fixed_dt2_no_subsample','exp_008c_fixed_dt2_no_subsample_h8','exp_008e_v3_subsample_on_dt1_h15','exp_008f_no_dt_embed_subsample_on_h8']
targets = [5000,15000,25000,35000,45000,55000,65000,75000,85000,95000,105000]
for exp in exps:
    path = os.path.join(base, exp, 'metrics.jsonl')
    data = {}
    with open(path) as f:
        for line in f:
            r = json.loads(line)
            s = r.get('step')
            if s in targets and 'actor_entropy' in r:
                data[s] = {'ae': r['actor_entropy'], 'al': r.get('actor_loss',''), 'vm': r.get('value_mean',''), 'er': r.get('eval_return','')}
    print(f'=== {exp} ===')
    for s in sorted(data):
        d = data[s]
        print(f'  step={s} actor_entropy={d[\"ae\"]:.4f} actor_loss={d[\"al\"]:.4f} value_mean={d[\"vm\"]:.4f}')
    if not data:
        print('  NO actor_entropy data found')
"
